package ru.zoldrax;
import net.fabricmc.api.ClientModInitializer;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.client.*;
import net.minecraft.client.util.ScreenshotRecorder;
import net.minecraft.block.*;
import net.minecraft.item.*;
import net.minecraft.util.math.*;
import net.minecraft.world.GameMode;
/** Reproducible development-only client review; never included in the release JAR. */
public final class MonkeyDecorClientPreview implements ClientModInitializer {
 private int ticks,step=-1;private boolean setup;private final java.io.File out=new java.io.File("monkey-review");
 private static final DecorKind[] KINDS={DecorKind.FOOD_SHELF,DecorKind.PREPARATION_TABLE,DecorKind.SUPPLY_BASKET,DecorKind.DRYING_RACK,DecorKind.COURTYARD_GONG,DecorKind.FESTIVAL_BENCH,DecorKind.NOTICE_BOARD,DecorKind.FESTIVAL_DRUM};
 static BlockPos root(int i){return new BlockPos(10+i*8,70,10);}
 public void onInitializeClient(){if(!Boolean.getBoolean("zoldrax.monkeyPreview"))return;ClientTickEvents.END_CLIENT_TICK.register(this::tick);}
 private void tick(MinecraftClient c){if(c.world==null||c.player==null||c.getServer()==null)return;
  if(!setup){setup=true;out.mkdirs();c.options.hudHidden=true;c.getTutorialManager().setStep(net.minecraft.client.tutorial.TutorialStep.NONE);c.options.getFov().setValue(55);c.options.getViewDistance().setValue(5);c.getServer().execute(()->{var w=c.getServer().getOverworld();w.setTimeOfDay(6000);w.getGameRules().get(net.minecraft.world.GameRules.DO_DAYLIGHT_CYCLE).set(false,c.getServer());var p=c.getServer().getPlayerManager().getPlayer(c.player.getUuid());p.changeGameMode(GameMode.SPECTATOR);p.stopRiding();
   var saved=w.getBlockEntity(root(0));if(saved instanceof DecorBlockEntity e&&!e.isEmpty())System.out.println("MONKEY_RELOAD_VERIFIED food_shelf_items="+e.count(Items.APPLE));
   for(int i=0;i<8;i++){var r=root(i);for(var pos:BlockPos.iterate(r.getX()-4,69,4,r.getX()+5,77,17))w.setBlockState(pos,pos.getY()==69?Blocks.JUNGLE_PLANKS.getDefaultState():Blocks.AIR.getDefaultState(),3);for(int x=0;x<KINDS[i].width;x++)w.setBlockState(r.add(x,-1,0),Blocks.SEA_LANTERN.getDefaultState(),3);var b=DecorBlocks.BLOCKS.get(KINDS[i]);var s=b.getDefaultState();w.setBlockState(r,s,3);b.onPlaced(w,r,s,p,new ItemStack(b));}
  });return;}
  if(++ticks==10&&step==-1)c.getServer().execute(()->{var w=c.getServer().getOverworld();for(var e:w.getEntitiesByClass(net.minecraft.entity.ItemEntity.class,new Box(0,60,0,100,90,30),e->true))e.discard();});if(ticks<35)return;ticks=0;
  if(step>=0)ScreenshotRecorder.saveScreenshot(out,String.format("%02d-",step)+(step<40?KINDS[step/5].id+new String[]{"-empty","-filled","-side","-back","-top"}[step%5]:step>=44?"combo-"+step:step==40?"all-vanilla-foods":step==41?"basket-menu":step==42?"bench-seated":"monkey-tab")+".png",c.getFramebuffer(),t->System.out.println("MONKEY_SCREENSHOT "+step));
  ++step;if(Boolean.getBoolean("zoldrax.monkeyBoardOnly")&&step==0)step=30;if(Boolean.getBoolean("zoldrax.monkeyPrepOnly")&&step==0)step=5;if(Boolean.getBoolean("zoldrax.monkeyPrepOnly")&&step==10)step=15;if(Boolean.getBoolean("zoldrax.monkeyPrepOnly")&&step==20)step=46;if(step>=50||Boolean.getBoolean("zoldrax.monkeyPrepOnly")&&step>=48||Boolean.getBoolean("zoldrax.monkeyBoardOnly")&&step>=35){System.out.println("MONKEY_PREVIEW_COMPLETE");c.scheduleStop();return;}
  final int target=step;c.setScreen(null);
  if(step>=44){int i=step<46?0:step<48?1:2;var r=root(i);c.getServer().execute(()->{var w=c.getServer().getOverworld();var p=c.getServer().getPlayerManager().getPlayer(c.player.getUuid());p.stopRiding();p.changeGameMode(GameMode.SPECTATOR);p.networkHandler.requestTeleport(r.getX()+KINDS[i].width/2.0,70+(i==2?2:1.8),r.getZ()+5.5,180,i==2?25:15);var e=(DecorBlockEntity)w.getBlockEntity(r);e.clear();var food=target%2==0?Items.APPLE:Items.CARROT;for(int j=0;j<e.size();j++)e.setStack(j,new ItemStack(food,i==2?32:1));});return;}
  if(step<40){int i=step/5,view=step%5;var r=root(i);double cx=r.getX()+KINDS[i].width/2.0,cy=r.getY()+KINDS[i].height/2.0;double dx=view==2?5:0,dz=view==4?.001:view==3?-5:view==2?0:5;float yaw=view==2?90:view==3?0:180;c.getServer().execute(()->{var w=c.getServer().getOverworld();var p=c.getServer().getPlayerManager().getPlayer(c.player.getUuid());p.networkHandler.requestTeleport(cx+dx,cy+(view==4?5:i==2?2:.8)-1.62,r.getZ()+.5+dz,yaw,view==4?90:i==2?22:9);var e=(DecorBlockEntity)w.getBlockEntity(r);if(view==1){if(KINDS[i].foodDisplay()){Item[] foods={Items.APPLE,Items.BREAD,Items.CARROT,Items.COD,Items.BEEF,Items.MELON_SLICE,Items.COOKIE,Items.HONEY_BOTTLE,Items.GOLDEN_APPLE};for(int j=0;j<e.size();j++)e.setStack(j,new ItemStack(foods[j],KINDS[i]==DecorKind.SUPPLY_BASKET?32:1));}if(KINDS[i]==DecorKind.NOTICE_BOARD){e.setStack(0,new ItemStack(Items.PAPER));var map=FilledMapItem.createMap(w,0,0,(byte)0,true,false);((FilledMapItem)Items.FILLED_MAP).updateColors(w,p,FilledMapItem.getMapState(map,w));e.setStack(1,map);e.setStack(2,new ItemStack(Items.BOOK));}if(KINDS[i]==DecorKind.COURTYARD_GONG||KINDS[i]==DecorKind.FESTIVAL_DRUM)e.strike();}});
  }else c.getServer().execute(()->{var w=c.getServer().getOverworld();var p=c.getServer().getPlayerManager().getPlayer(c.player.getUuid());if(target==40){int index=0;for(var item:net.minecraft.registry.Registries.ITEM){if(!net.minecraft.registry.Registries.ITEM.getId(item).getNamespace().equals("minecraft")||!item.isFood())continue;int row=index/6,col=index%6;var r=new BlockPos(10+col*3,70,30+row*2);w.setBlockState(r.down(),Blocks.JUNGLE_PLANKS.getDefaultState());var b=DecorBlocks.BLOCKS.get(DecorKind.PREPARATION_TABLE);w.setBlockState(r,b.getDefaultState());b.onPlaced(w,r,b.getDefaultState(),p,new ItemStack(b));((DecorBlockEntity)w.getBlockEntity(r)).setStack(0,new ItemStack(item));index++;}p.networkHandler.requestTeleport(19,88,37,0,90);}if(target==41){var r=root(2);p.changeGameMode(GameMode.CREATIVE);p.networkHandler.requestTeleport(r.getX()+.5,70,r.getZ()+3,180,10);((DecorBlockEntity)w.getBlockEntity(r)).use(p,net.minecraft.util.Hand.MAIN_HAND);}if(target==42){var r=root(5);p.networkHandler.requestTeleport(r.getX()+1,70,r.getZ()+3,0,10);((DecorBlockEntity)w.getBlockEntity(r)).sitOnBench(p);c.execute(()->c.options.setPerspective(net.minecraft.client.option.Perspective.THIRD_PERSON_FRONT));}if(target==43)c.execute(()->{c.options.setPerspective(net.minecraft.client.option.Perspective.FIRST_PERSON);var screen=new net.minecraft.client.gui.screen.ingame.CreativeInventoryScreen(c.player,c.player.networkHandler.getEnabledFeatures(),true);c.setScreen(screen);var group=net.minecraft.registry.Registries.ITEM_GROUP.get(DecorBlocks.id("monkey_decor"));var pages=(net.fabricmc.fabric.impl.client.itemgroup.CreativeGuiExtensions)screen;int page=((net.fabricmc.fabric.impl.itemgroup.FabricItemGroup)group).getPage();while(pages.fabric_currentPage()<page)pages.fabric_nextPage();try{var method=screen.getClass().getDeclaredMethod("setSelectedTab",net.minecraft.item.ItemGroup.class);method.setAccessible(true);method.invoke(screen,group);}catch(Exception e){throw new RuntimeException(e);}});});
 }
}
